import typing

from ...base.client import BaseClient


class AntispamMethods(BaseClient):
    """
    Методы группы 'Антиспам' из https://im-docs.corp.mail.ru/
    """

    async def rapi_reportAbuse(
        self,
        reason: typing.Literal["spam", "porno", "violation", "other"],
        context_json: dict,
    ):
        """
        Пожаловаться на сообщение в чате
        """
        context_json["reason"] = reason

        return await self.post(
            "rapi/reportAbuse",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": context_json,
            },
        )
